'use strict';

// MODULES //

var serialize = require( '@stdlib/ndarray/base/serialize-meta-data' );
var reinterpretBoolean = require( '@stdlib/strided/base/reinterpret-boolean' );
var getData = require( '@stdlib/ndarray/base/data-buffer' );
var getDType = require( '@stdlib/ndarray/base/dtype' );
var getShape = require( '@stdlib/ndarray/base/shape' );
var getStride = require( '@stdlib/ndarray/base/stride' );
var getOffset = require( '@stdlib/ndarray/base/offset' );
var canUseNative = require( './can_use_native.js' );
var main = require( './main.js' );
var addon = require( './../src/addon.node' );


// FUNCTIONS //

/**
* Serializes the current view without using cached or custom metadata.
*
* @private
* @param {ndarrayLike} x - input ndarray
* @returns {DataView} serialized metadata
*/
function metaData( x ) {
	return serialize({
		'dtype': getDType( x ),
		'shape': getShape( x, false ),
		'strides': [ getStride( x, 0 ) ],
		'offset': getOffset( x ),
		'order': x.order
	});
}


// MAIN //

/**
* Takes elements from one of two one-dimensional double-precision floating-point ndarrays depending on a condition.
*
* @private
* @param {ArrayLikeObject<Object>} arrays - array-like object containing ndarrays
* @returns {ndarray} output ndarray
*
* @example
* var BooleanVector = require( '@stdlib/ndarray/vector/bool' );
* var Float64Vector = require( '@stdlib/ndarray/vector/float64' );
*
* var condition = new BooleanVector( [ true, false, true ] );
* var x = new Float64Vector( [ 1.0, 2.0, 3.0 ] );
* var y = new Float64Vector( [ 4.0, 5.0, 6.0 ] );
* var out = new Float64Vector( 3 );
*
* var v = dwhere( [ condition, x, y, out ] );
* // returns <ndarray>[ 1.0, 5.0, 3.0 ]
*/
function dwhere( arrays ) {
	var condition;
	var views;
	var out;
	var x;
	var y;

	condition = arrays[ 0 ];
	x = arrays[ 1 ];
	y = arrays[ 2 ];
	out = arrays[ 3 ];
	views = [ condition, x, y, out ];
	if ( !canUseNative( views ) ) {
		return main( views );
	}
	addon( reinterpretBoolean( getData( condition ), 0 ), metaData( condition ), getData( x ), metaData( x ), getData( y ), metaData( y ), getData( out ), metaData( out ) ); // eslint-disable-line max-len
	return out;
}


// EXPORTS //

module.exports = dwhere;
